77	/**
78	 * An open transaction against FDB.
79	 *
80	 * <p>
81	 * All reads and writes to the database are transactional: an open {@code FDBRecordContext} is needed.
82	 * An {@link FDBDatabase} is needed to open an {@code FDBRecordContext}.
83	 * </p>
84	 *
85	 * <pre><code>
86	 * final FDBDatabase fdb = FDBDatabaseFactory.instance().getDatabase();
87	 * try (FDBRecordContext ctx = fdb.openContext()) {
88	 *     ...
89	 * }
90	 * </code></pre>
91	 *
92	 * @see FDBRecordStore
93	 */
94	@API(API.Status.STABLE)
95	public class FDBRecordContext extends FDBTransactionContext implements AutoCloseable {
96	    private static final Logger LOGGER = LoggerFactory.getLogger(FDBRecordContext.class);
97	    private static final byte[] META_DATA_VERSION_STAMP_VALUE = new byte[FDBRecordVersion.GLOBAL_VERSION_LENGTH + Integer.BYTES];
98	    private static final long UNSET_VERSION = 0L;
